from collections import defaultdict, deque

def comps_stats(g):
 h,w=len(g),len(g[0]); seen=set(); stats=[]
 for r in range(h):
  for c in range(w):
   if (r,c) in seen: continue
   col=g[r][c]; q=[(r,c)];seen.add((r,c));cells=[]
   while q:
    y,x=q.pop();cells.append((y,x))
    for ny,nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
     if 0<=ny<h and 0<=nx<w and (ny,nx) not in seen and g[ny][nx]==col:
      seen.add((ny,nx));q.append((ny,nx))
   ys=[x[0] for x in cells];xs=[x[1] for x in cells]
   area=(max(ys)-min(ys)+1)*(max(xs)-min(xs)+1)
   stats.append((len(cells),col,(min(ys),max(ys),min(xs),max(xs)),round(len(cells)/area,2)))
 return sorted(stats,reverse=True)
